using System.Windows;using System.Windows.Controls;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class OrdersWindow:Window{private readonly OrderService022 _svc;public Order022? SelectedOrder{get;private set;}public string Action{get;private set;}="";public OrdersWindow(OrderService022 svc){_svc=svc;InitializeComponent();Loaded+=async(_,_)=>await Refresh();}private string Status=>StatusBox.SelectedItem is ComboBoxItem i?Convert.ToString(i.Content)??"AwaitingPayment":"AwaitingPayment";private async Task Refresh()=>Grid.ItemsSource=await _svc.SearchAsync(SearchBox.Text,Status);private async void Search_Click(object sender,RoutedEventArgs e)=>await Refresh();private Order022? Pick(){if(Grid.SelectedItem is not Order022 o){MessageBox.Show("Selecione um pedido.","Pedidos");return null;}return o;}private void Print_Click(object sender,RoutedEventArgs e){var o=Pick();if(o is null)return;if(MessageBox.Show($"Deseja imprimir o pedido {o.Number:000000}?","Imprimir pedido",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;try{var dlg=new PrintDialog();if(dlg.ShowDialog()!=true)return;var doc=new System.Windows.Documents.FlowDocument{PagePadding=new Thickness(25),FontFamily=new System.Windows.Media.FontFamily("Consolas"),FontSize=12};var p=doc.Blocks;p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run("ONÇA PRODUTOS DE LIMPEZA")){FontWeight=FontWeights.Bold,FontSize=16});p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"PEDIDO Nº {o.Number:000000}")));p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Data: {o.CreatedAt:dd/MM/yyyy HH:mm}")));p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Cliente: {o.Customer}")));if(!string.IsNullOrWhiteSpace(o.Phone))p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Telefone: {o.Phone}")));p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run("----------------------------------------")));foreach(var item in o.Items)p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"{item.Quantity:0.###} x {item.Name}\n  {item.UnitPrice:C} = {item.Subtotal:C}")));if(o.Discount!=0)p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Desconto: {o.Discount:C}")));p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"TOTAL: {o.Total:C}")){FontWeight=FontWeights.Bold,FontSize=15});if(!string.IsNullOrWhiteSpace(o.Notes))p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Observações: {o.Notes}")));p.Add(new System.Windows.Documents.Paragraph(new System.Windows.Documents.Run($"Status: {o.Status}")));var paginator=((System.Windows.Documents.IDocumentPaginatorSource)doc).DocumentPaginator;dlg.PrintDocument(paginator,$"Pedido {o.Number:000000} - ONÇA");MessageBox.Show("Pedido enviado para a impressora.","Imprimir pedido",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){MessageBox.Show("Não foi possível imprimir o pedido.\n\n"+ex.Message,"Imprimir pedido",MessageBoxButton.OK,MessageBoxImage.Warning);}}private void Edit_Click(object sender,RoutedEventArgs e){var o=Pick();if(o is null)return;if(o.Status!="AwaitingPayment"){MessageBox.Show("Somente pedido aguardando pagamento pode ser editado.");return;}SelectedOrder=o;Action="Edit";DialogResult=true;}private void Pay_Click(object sender,RoutedEventArgs e){var o=Pick();if(o is null)return;if(o.Status!="AwaitingPayment"){MessageBox.Show("Este pedido não está aguardando pagamento.");return;}SelectedOrder=o;Action="Pay";DialogResult=true;}private async void Cancel_Click(object sender,RoutedEventArgs e){var o=Pick();if(o is null)return;if(MessageBox.Show($"Cancelar o pedido {o.Number:000000}?\n\nNada será lançado no caixa.","Pedidos",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{await _svc.CancelAsync(o.Id);await Refresh();}catch(Exception ex){MessageBox.Show(ex.Message,"Pedidos",MessageBoxButton.OK,MessageBoxImage.Warning);}}}